const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function storeName(){try{return localStorage.getItem('qadam.storeName')||'Мой магазин';}catch{return 'Мой магазин';}}
function identity(){document.querySelector('.workspace strong').textContent=storeName();document.querySelector('.store-icon').textContent=storeName().slice(0,1).toUpperCase();}
export function workspacePage(){return `<div class="page-head"><div><h1>Магазин и помощь</h1><p class="subtitle">Настройте рабочее пространство и начните с ваших продаж.</p></div><span class="badge">Один магазин · KZT</span></div><section class="panel"><h2>Ваш магазин</h2><form id="store-form" class="budget-form"><label for="store-name">Название магазина<input id="store-name" maxlength="80" required value="${esc(storeName())}" placeholder="Например, Асыл Market"></label><button class="button primary" type="submit">Сохранить название</button></form><p class="meta">Название сохраняется только в этом браузере. Продажи и заказы хранятся отдельно на сервере. Валюта — тенге; даты напоминаний — по времени Алматы.</p></section><section class="panel"><h2>Первый рабочий день с Qadam</h2><ol class="guide-list"><li><strong>Подготовьте продажи</strong><p>Выгрузите данные из своей системы учёта и приведите к шаблону CSV: товар, дата, продажи, цены и остатки. Для предварительного прогноза нужны 7 последовательных дней, для сравнения методов — 42.</p><a href="#import">Загрузить продажи →</a></li><li><strong>Проверьте цифры</strong><p>Сверьте выручку и остатки с системой учёта. Валовая прибыль здесь — выручка минус себестоимость, без аренды, налогов и комиссий.</p><a href="#overview">Открыть обзор →</a></li><li><strong>Составьте закупку</strong><p>Проверьте срок поставки и товар в пути. При ограниченном бюджете рассчитайте сценарий и перенесите выбранные количества в заказ.</p><a href="#actions">Рассчитать закупку →</a></li><li><strong>Согласуйте заказ</strong><p>Укажите поставщика, проверьте товары и количество. Затем скопируйте текст или подтвердите отправку через подключённого Telegram-бота.</p><a href="#suppliers">Открыть заказы →</a></li></ol></section><section class="panel"><h2>Частые вопросы</h2><details><summary>Что происходит при новой загрузке?</summary><p class="note">Файл содержит полную историю и актуальные остатки. Новый набор заменяет текущий после успешной проверки и сохранения. Предыдущие наборы доступны в истории загрузок; восстановление не удаляет другие версии. До 5 000 строк и 1 МБ в файле; до 100 разных снимков каждого типа.</p></details><details><summary>Как сохранить копию моих данных?</summary><p class="note">В обзоре есть кнопка «Скачать продажи». В плане закупок и прогнозе доступны отдельные выгрузки. Ниже можно скачать архив текущих продаж, рекламы и всех заказов в формате JSON. Храните его в надёжном месте; автоматический импорт такого архива не предусмотрен.</p><button class="button" id="download-backup">Скачать копию данных JSON</button><p id="backup-status" class="meta" role="status"></p></details><details><summary>Почему закупка не изменила остатки?</summary><p class="note">Qadam помогает планировать закупки. Отметки об оплате и получении не меняют склад. После поставки обновите остатки в своей системе учёта и загрузите новый CSV.</p></details><details><summary>Что пока нужно делать в других системах?</summary><p class="note">Кассовые операции, бухгалтерия, налоги, возвраты, движение склада и банковские платежи ведутся в ваших действующих системах. Прямое подключение маркетплейсов и рекламных кабинетов пока отсутствует. Прогноз — рекомендация; перед закупкой проверьте актуальность данных и наличие товара у поставщика.</p></details><details><summary>Кто видит данные?</summary><p class="note">Доступ к сайту ограничен приглашёнными пользователями. Продажи и заказы привязаны к вошедшему пользователю. В этой версии нет общего магазина для нескольких сотрудников и распределения ролей.</p></details></section>`;}
export function mountWorkspace(app,notify){
  app.querySelector('#store-form').onsubmit=e=>{e.preventDefault();const value=app.querySelector('#store-name').value.trim();if(!value){notify('Укажите название магазина.');return;}try{localStorage.setItem('qadam.storeName',value);identity();notify('Название сохранено в этом браузере.');}catch{notify('Браузер не разрешает сохранять настройки.');}};
  app.querySelector('#download-backup').onclick=async e=>{const b=e.currentTarget,status=app.querySelector('#backup-status');b.disabled=true;status.textContent='Собираем сохранённые данные…';try{
    const data=await Promise.all(['datasets/sales','datasets/marketing','orders'].map(async path=>{const response=await fetch('./api/'+path,{signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('Не удалось получить все данные. Повторите скачивание позже.');return response.json();}));
    const backup={format:'qadam-export-v1',exportedAt:new Date().toISOString(),sales:data[0].dataset,marketing:data[1].dataset,orders:data[2].orders};
    const u=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='qadam-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);status.textContent='Копия скачана. Она содержит текущие наборы данных и все заказы.';
  }catch(error){status.textContent=error.message;}finally{b.disabled=false;}};
}
export function decorateWorkspace(app,view,state,result){
  identity();
  if(view==='overview'){
    const head=app.querySelector('.page-head');
    head.insertAdjacentHTML('beforeend','<button class="button" id="export-sales">↓ Скачать продажи</button>');
    if(state.source==='demo')head.insertAdjacentHTML('afterend',`<section class="welcome-card"><div><span class="eyebrow">НАЧНИТЕ С ВАШЕГО МАГАЗИНА</span><h2>От продаж к понятной закупке</h2><p>Сейчас вы видите учебный магазин. Загрузите CSV, чтобы получить обзор продаж и план пополнения своего ассортимента.</p><div class="toolbar"><a class="button primary" href="#import">Загрузить свои продажи →</a><a class="button" href="#workspace">Как начать</a>${state.savedDataset?'<button id="return-saved" class="button">Вернуться к моим данным</button>':''}</div></div><div class="welcome-steps"><span><b>01</b> Загрузите CSV</span><span><b>02</b> Проверьте прогноз</span><span><b>03</b> Подготовьте закупку</span></div></section>`);
    else {
      const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Almaty'}).format(new Date()),age=Math.floor((Date.parse(today)-Date.parse(result.end))/86400000);
      if(age>2)head.insertAdjacentHTML('afterend',`<div class="freshness-warning" role="status"><strong>Обновите остатки перед закупкой</strong><span>Последние продажи — ${esc(result.end)}, ${age} дн. назад. План рассчитан на дату этих данных.</span><a href="#import">Загрузить свежие данные →</a></div>`);
    }
  }
}
